INSERT INTO `v1_d5dad172b94afe653a7df306ee1e45f6f512bca28ebbb429792c6df9087f1725` VALUES (1, "スタンダードコレクション", 1, "1回メダル{0}枚！\n定番グッズであなたの部屋をカルミナで彩ろう！", 3, "スタンダードコレクションではポスターやペナントなど\n部屋に飾れる定番グッズが盛りだくさん！\nあなたの部屋をカルミナで彩ろう！");
INSERT INTO `v1_d5dad172b94afe653a7df306ee1e45f6f512bca28ebbb429792c6df9087f1725` VALUES (1, "プレミアムコレクション", 2, "1回メダル{0}枚！\nメンバー直筆サイン色紙など、★★以上のグッズを確定でゲット！", 10, "プレミアムコレクションではサイン色紙や\nブロマイドなど、★★以上のグッズが盛りだくさん！\nレアグッズをたくさんゲットしよう！");
INSERT INTO `v1_d5dad172b94afe653a7df306ee1e45f6f512bca28ebbb429792c6df9087f1725` VALUES (1, "フェスコレクション", 3, "1回メダル{0}枚！\nカルミナライブに参加する際のマストアイテムをゲットしよう！", 3, "フェスコレクションではカルミナサマーライブで\n大活躍するグッズが勢ぞろい！\nゲットしたグッズを片手に、いざライブ会場へ！");
